// This file was generated with the assistance of an AI coding tool.

// Replays calls recorded from the Python test suite (src/transpiler/parity/record.py)
// against TypeScript generated by src/transpiler/generate.py. A call is skipped,
// with the reason, when its Python test did not pass, its module or function was
// not transpiled, or its arguments could not be recorded. The generated code is
// imported from dist/python, so `npm run generate` and `npm run build` come first.

import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { beforeAll, describe, expect, it } from 'vitest';
import * as ifcopenshell from 'ifcopenshell';
import { createInstance, describeOrSkip } from '../_helper.js';
import { changes, decode, difference, encode, graph, Unreplayable, type Changes, type Encoded } from './values.js';

interface RecordedCall {
  function: string;
  args?: Encoded[];
  options?: Record<string, Encoded>;
  files?: string[];
  state?: Record<string, Encoded>[];
  max_ids?: number[];
  owner?: 'create' | 'existing' | 'default';
  expected?: Encoded;
  raises?: string;
  after?: { state: Record<string, Encoded>; changes?: Changes }[];
  skip?: string;
}

interface Golden {
  module: string;
  /** Distinct STEP lines; each file snapshot lists the indices of its lines. */
  lines: string[];
  files: Record<string, number[]>;
  tests: { test: string; outcome: string; calls: RecordedCall[] }[];
}

interface ManifestEntry {
  source: string;
  error?: string;
  stubs?: Record<string, string>;
}

const here = dirname(fileURLToPath(import.meta.url));
const goldenDir = resolve(here, '../../../../transpiler/parity/golden');
const built = resolve(here, '../../dist/python');
const manifestPath = resolve(here, '../../src/python/transpile.json');
const manifest: Record<string, ManifestEntry> = existsSync(manifestPath) ? JSON.parse(readFileSync(manifestPath, 'utf8')) : {};
const goldens: Golden[] = existsSync(goldenDir)
  ? readdirSync(goldenDir).filter(f => f.endsWith('.json')).sort()
    .map(f => JSON.parse(readFileSync(resolve(goldenDir, f), 'utf8')))
  : [];

/** Generated module of a recorded Python function: util/<module> or api/<package>/<usecase>. */
function generated(module: string, fn: string): string {
  const [scope, name] = module.split('.') as ['util' | 'api', string];
  return scope === 'util' ? `util/${name}` : `api/${name}/${fn}`;
}

/** Fail with the first difference in full; vitest truncates long values in its own messages. */
function same(actual: Encoded, expected: Encoded, label: string): void {
  const found = difference(actual, expected);
  if (found) throw new Error(`${label}: ${found}`);
}

/** Python names become camelCase in generated code. */
const camel = (python: string) => python.replace(/_([a-z0-9])/g, (_, c: string) => c.toUpperCase());

function skipReason(golden: Golden, outcome: string, call: RecordedCall): string | null {
  if (outcome !== 'passed') return `Python test ${outcome}`;
  if (call.skip) return call.skip;
  const entry = manifest[generated(golden.module, call.function)];
  if (!entry) return 'not generated (run npm run generate)';
  if (entry.error) return `not transpiled: ${entry.error}`;
  if (entry.stubs?.[call.function]) return `stub: ${entry.stubs[call.function]}`;
  return null;
}

const schemaPlugins: Record<string, string> = { IFC2X3: 'ifc2x3', IFC4: 'ifc4', IFC4X3: 'ifc4x3_add2', IFC4X3_ADD2: 'ifc4x3_add2' };

if (!goldens.length) describe.skip('parity with Python (no recordings; run npm run record)', () => {});

describeOrSkip('parity with Python', () => {
  let runtime: ifcopenshell.IfcOpenShell;
  const loaded = new Set<string>();
  beforeAll(async () => {
    runtime = await createInstance();
    ownerOverrides = (await import(pathToFileURL(resolve(built, 'api/owner/settings.js')).href)).overrides;
  });

  let ownerOverrides: Record<string, ((file: ifcopenshell.File) => unknown) | undefined>;

  /** Owner settings as the Python test had them; see owner_mode() in record.py and test/bootstrap.py. */
  function setOwnerMode(mode: RecordedCall['owner']): void {
    const create = mode === 'create';
    ownerOverrides.getUser = mode === 'default' ? undefined : (file) => file.byType('IfcPersonAndOrganization')[0]
      ?? (create
        ? file.create('IfcPersonAndOrganization', { ThePerson: file.create('IfcPerson'), TheOrganization: file.create('IfcOrganization') })
        : null);
    ownerOverrides.getApplication = mode === 'default' ? undefined : (file) => file.byType('IfcApplication')[0]
      ?? (create ? file.create('IfcApplication') : null);
  }

  async function openSnapshot(spf: string): Promise<ifcopenshell.File> {
    const schema = /FILE_SCHEMA\s*\(\s*\(\s*'([^']+)'/i.exec(spf)?.[1]?.toUpperCase() ?? 'IFC4';
    const plugin = schemaPlugins[schema];
    if (!plugin) throw new Unreplayable(`no schema plugin for ${schema}`);
    if (!loaded.has(plugin)) {
      await runtime.loadPlugin('schema', plugin);
      loaded.add(plugin);
    }
    return ifcopenshell.open(new TextEncoder().encode(spf));
  }

  for (const golden of goldens) {
    describe(golden.module, () => {
      if (!golden.tests.length) it.skip('no calls recorded from the Python tests', () => {});
      for (const { test, outcome, calls } of golden.tests) {
        calls.forEach((call, index) => {
          const reason = skipReason(golden, outcome, call);
          const name = `${test.replace(/^.*?::/, '')} [${index}] ${call.function}`;
          if (reason) {
            it.skip(`${name} (${reason})`, () => {});
            return;
          }
          it(name, async () => {
            const path = resolve(built, `${generated(golden.module, call.function)}.js`);
            const module = await import(pathToFileURL(path).href);
            const fn = module[camel(call.function)];
            expect(fn, `${camel(call.function)} exported from ${path}`).toBeTypeOf('function');

            const files = await Promise.all((call.files ?? []).map(digest => (
              openSnapshot(golden.files[digest]!.map(line => golden.lines[line]).join('\n'))
            )));
            try {
              setOwnerMode(call.owner ?? 'existing');
              // New ids continue from Python's counter, which may be past the snapshot's largest id.
              call.max_ids?.forEach((maxId, i) => {
                while (files[i]!.getMaxId() < maxId) files[i]!.freshId();
              });
              call.state?.forEach((state, i) => {
                for (const [key, value] of Object.entries(state)) {
                  (files[i] as unknown as Record<string, unknown>)[key] = decode(value, files);
                }
              });
              const before = call.after?.map((after, i) => (after.changes ? graph(files[i]!, files) : null));
              const args = (call.args ?? []).map(arg => decode(arg, files));
              // Optional Python parameters become a trailing options object with camelCase keys.
              if (call.options) {
                args.push(decode({ $dict: Object.entries(call.options).map(([k, v]) => [camel(k), v]) }, files));
              }

              if (call.raises) {
                expect(() => fn(...args), `Python raised ${call.raises}`).toThrow();
              } else {
                const result = encode(fn(...args), files);
                same(result, call.expected ?? null, 'return value');
              }

              call.after?.forEach((after, i) => {
                const file = files[i]!;
                const state = Object.fromEntries(Object.keys(after.state).map(key => [
                  key, encode((file as unknown as Record<string, unknown>)[key], files),
                ]));
                same(state, after.state, 'file state after the call');
                if (after.changes) {
                  const actual = changes(before![i]!, graph(file, files));
                  same(actual as unknown as Encoded, after.changes as unknown as Encoded, 'file changes made by the call');
                }
              });
            } finally {
              files.forEach(file => file.dispose());
            }
          });
        });
      }
    });
  }
});
